{
 "proposal_memo": {
  "from": "VP Retail Deposit Products",
  "to": "Fee & Pricing Committee",
  "date": "2026-09-02",
  "text": "Cedar Mutual Bank proposes a modest set of research and document fees to recover servicing costs, effective after committee and board approval. Section 1034(c) restrictions do not affect us: Cedar Mutual has $9.4 billion in total assets, below the $10 billion threshold. To keep the proposal customer-friendly, no fee will be charged for balance inquiries in any channel, and digital self-service (statements and check images inside online banking for the last 12 months) remains free."
 },
 "draft_fee_schedule": [
  {
   "line": "L1",
   "service": "Check image copy, paper or PDF, requested from a banker",
   "fee": "$10.00 per item"
  },
  {
   "line": "L2",
   "service": "Account history research older than 12 months",
   "fee": "$25.00 per hour, 1-hour minimum"
  },
  {
   "line": "L3",
   "service": "Loan payoff statement, written or verbal",
   "fee": "$15.00 per request"
  },
  {
   "line": "L4",
   "service": "Copy of the deposit account agreement",
   "fee": "$5.00 per copy"
  },
  {
   "line": "L5",
   "service": "Telephone banker assistance for transfers or bill payments made on the customer's behalf",
   "fee": "$3.00 per call (not applied to balance inquiries)"
  },
  {
   "line": "L6",
   "service": "Cashier's check",
   "fee": "$10.00 per check"
  },
  {
   "line": "L7",
   "service": "Expedited debit card delivery",
   "fee": "$25.00 per card"
  }
 ],
 "call_report_excerpt": {
  "form": "FFIEC 041, Schedule RC (Balance Sheet)",
  "report_date": "2026-06-30",
  "item_12_total_assets_thousands_usd": "10,612,447",
  "note": "Includes Ridgeway Savings Bank, acquired and merged into Cedar Mutual on 2026-04-30."
 },
 "annual_report_2025_excerpt": "As of December 31, 2025, Cedar Mutual Bank reported total assets of $9.38 billion, total deposits of $7.91 billion and a CET1 ratio of 11.8%.",
 "policy_digest_1034c": "Compliance digest CD-14 (Information requests). Scope: applies when Cedar Mutual's total assets exceed $10 billion, measured using the total assets reported in the most recent quarterly Call Report. Rule: do not charge any fee for responding to a consumer's request for information about the consumer's own account - including balances, transaction history, payoff amounts, check images, copies of the account agreement and research time. Fees for services other than providing information (e.g., cashier's checks, wire transfers, expedited card delivery, transactions performed on the customer's behalf) are outside CD-14.",
 "legal_comments": [
  {
   "author": "Deputy General Counsel",
   "date": "2026-09-09",
   "text": "The memo uses the year-end 2025 figure. The June 30 Call Report already reflects the Ridgeway merger. Please re-check coverage before the vote."
  },
  {
   "author": "Finance - Regulatory Reporting",
   "date": "2026-09-10",
   "text": "Confirmed: total assets on the 2026-06-30 Call Report are as filed; no amendment pending."
  }
 ],
 "committee_minutes": "Fee & Pricing Committee, 2026-09-11. Present: CFO (chair), VP Retail Deposit Products, Deputy GC, Head of Compliance, Head of Branch Network. Item 3 - research and document fees: discussion of coverage question raised by Legal. Branch Network supports L6 and L7 as market-standard. Decision: item deferred to the October meeting pending a written coverage analysis from Compliance. No fee to be communicated to customers before then."
}
